package application.domain.services.order;
import application.domain.model.*; import application.domain.ports.in.*; import application.domain.ports.out.*; import application.domain.services.ServiceSupport; import java.util.*;
public class CancelOrderService implements CancelOrderUseCase { private final OrderRepositoryPort orders; private final InventoryRepositoryPort inventories; private final OperationAuditPort audit; public CancelOrderService(OrderRepositoryPort o,InventoryRepositoryPort i,OperationAuditPort a){orders=o;inventories=i;audit=a;}
 public Order cancelOrder(User actor,String id){Order o=ServiceSupport.required(orders.findById(id),"Order",id);ServiceSupport.sameCustomer(actor,o.getCustomer());if(o.getStatus()==DomainTypes.OrderStatus.CANCELLED||o.getStatus()==DomainTypes.OrderStatus.DELIVERED||o.getStatus()==DomainTypes.OrderStatus.RETURNED)throw new application.domain.exceptions.DomainRuleException("Order cannot be cancelled");for(OrderItem item:o.getItems()){Inventory inv=ServiceSupport.required(inventories.findByProduct(item.product()),"Inventory",item.product().getId());if(inv.getReserved()>=item.quantity())inv.release(item.quantity());inventories.update(inv);}o.changeStatus(DomainTypes.OrderStatus.CANCELLED);orders.update(o);audit.record(actor,"CANCEL_ORDER",id,Map.of());return o;}
}
